const CYTOKINESIS=fig('Cytokinesis (schematics, not to scale)',{pts:{A:[2,2],B:[4,2.6],C:[6,2],D:[7,.6],E:[8,2],F:[10,2.6],G:[12,2],H:[12,-2],I:[10,-2.6],J:[8,-2],K:[7,-.6],L:[6,-2],M:[4,-2.6],N:[2,-2],O1:[4,0],O2:[10,0],P:[16,2.6],Q:[27,2.6],R:[27,-2.6],S:[16,-2.6],O3:[18.5,0],O4:[24.5,0],T:[21.5,-1.8],U:[21.5,1.8],V:[7,-3.3],W:[21.5,-3.3],X:[21.5,-2],Y:[21.5,0],Z:[21.5,2]},polys:[{v:'ABCDEFGHIJKLMN',col:0,fill:false},{v:'PQRS',col:2,fill:false}],circles:['O1','O2','O3','O4'].map(c=>({c,r:.85,col:3})),segs:[{v:'TU',col:1,w:4},{v:'YX',col:1,arrows:1},{v:'YZ',col:1,arrows:1},{v:'KV',col:0,w:1},{v:'TW',col:1,w:1}],notes:[{at:[7,3.7],text:'animal: membrane pinches inward'},{at:[21.5,3.7],text:'plant: outer wall remains'},{at:[7,-3.8],text:'cleavage furrow'},{at:[21.5,-3.8],text:'cell plate grows outward'},{at:[14,-4.8],text:'circles: daughter nuclei'}],dots:'',hide:'ABCDEFGHIJKLMNOPQRSTUVWXYZO1O2O3O4',view:[0,29,-5.5,5]});
const RECEPTOR=fig('Reception across a membrane (schematic, not to scale)',{pts:{A:[0,0],B:[24,0],C:[24,1],D:[0,1],E:[7,-.7],F:[9,-.7],G:[9,2],H:[7,2],L:[8,3],N:[18,-2]},hide:'ABCDEFGHLN',dots:'',polys:[{v:'ABCD',col:0},{v:'EFGH',col:1}],circles:[{c:'L',r:.45,col:2},{c:'N',r:.8,col:3}],notes:[{at:[15,3],text:'water-soluble ligand'},{at:[17,1.7],text:'outside cell'},{at:[3,-1.5],text:'surface receptor'},{at:[8,-3],text:'relay inside cell'},{at:[18,-3.5],text:'intracellular receptor'},{at:[18,-.7],text:'lipid-soluble signal enters'}],view:[-1,25,-4.5,4.5]});
const FEEDBACK={t:'plot',title:'Fictional recovery: x = minutes; y = concentration (units)',x:[0,10],y:[0,16],paths:[{pts:Array.from({length:101},(_,i)=>{const x=i/10;return [x,8+6*Math.exp(-x/2)];})}],lines:[{m:0,b:8,dash:true,label:'set point 8'}]};
const DNA={t:'plot',title:'Fictional cycle: x = hours; y = DNA per cell (C)',x:[0,12],y:[0,5],paths:[{pts:[[0,2],[4,2],[7,4],[10,4],[10,2],[12,2]]}],vlines:[{x:4,dash:true},{x:7,dash:true},{x:10,dash:true}],points:[{x:2,y:2,label:'G1'},{x:5.5,y:3,label:'S'},{x:8.5,y:4,label:'G2/M'},{x:11,y:2,label:'daughter'}]};
const MITOSIS=(()=>{const pts={},circles=[],segs=[],notes=[];let id=0;const line=(a,b,col=0,w=3)=>{const x='A'+id++,y='A'+id++;pts[x]=a;pts[y]=b;segs.push({v:x+y,col,w});};for(let i=0;i<4;i++){const cx=3+7*i;pts['O'+i]=[cx,0];circles.push({c:'O'+i,r:2.5,col:2});notes.push({at:[cx,3.4],text:['prophase','metaphase','anaphase','telophase'][i]});if(i<2){for(const [dx,dy] of (i?[[0,-.8],[0,.8]]:[[-.8,.6],[.8,-.6]])){line([cx+dx-.35,dy-.5],[cx+dx+.35,dy+.5]);line([cx+dx-.35,dy+.5],[cx+dx+.35,dy-.5]);}if(i)for(const y of [-.8,.8]){line([cx-2,0],[cx,y],1,1);line([cx+2,0],[cx,y],1,1);}}else for(const dx of [-1.4,1.4]){if(i===3){pts['N'+(dx<0?'1':'2')]=[cx+dx,0];circles.push({c:'N'+(dx<0?'1':'2'),r:.9,col:3});}for(const dy of [-.45,.45])line([cx+dx-.2,dy-.2],[cx+dx+.2,dy+.2]);}}notes.push({at:[13.5,-3.6],text:'Sisters separate; each pole receives a complete set'});return fig('Mitosis: a fictional 2n = 2 cell (schematic)',{pts,circles,segs,notes,dots:'',hide:Object.keys(pts).join(''),view:[0,27,-4.3,4.3]});})();
const CYCLIN={t:'plot',title:'Fictional cycle: x = time; y = protein amount (units)',x:[0,12],y:[0,8],paths:[{pts:[[0,1],[2,2],[4,3],[6,4],[8,6],[9,6],[10,1],[12,1]]}],lines:[{m:0,b:5,dash:true,label:'Cdk amount'}],points:[{x:8.5,y:6,label:'cyclin'},{x:10,y:1,label:'degradation'}]};
